using System;
using System.Collections.Generic;
using UnityEngine;

namespace GrimoireAegis.UI
{
    /// <summary>
    /// Frame timings for every sprite-sheet generated by tools/grimoire_art_v2.py.
    /// Loaded from Resources/Gen/anim/anim_index.json so art and code never drift apart.
    /// Sheets are horizontal strips of square frames: frameCount = width / height.
    /// </summary>
    public static class AnimLibrary
    {
#pragma warning disable 0649 // assigned by JsonUtility
        [Serializable] private class Entry { public string key; public int frames; public int[] durations; public bool loop; }
        [Serializable] private class Index { public Entry[] entries; }
#pragma warning restore 0649

        private static Dictionary<string, Entry> _entries;

        private static void EnsureLoaded()
        {
            if (_entries != null) return;
            _entries = new Dictionary<string, Entry>();
            var ta = Resources.Load<TextAsset>("Gen/anim/anim_index");
            if (ta == null) return;
            var idx = JsonUtility.FromJson<Index>(ta.text);
            if (idx?.entries == null) return;
            foreach (var e in idx.entries) _entries[e.key] = e;
        }

        public static int[] Durations(string key)
        {
            EnsureLoaded();
            return _entries.TryGetValue(key, out var e) ? e.durations : null;
        }

        public static bool Loops(string key)
        {
            EnsureLoaded();
            return _entries.TryGetValue(key, out var e) && e.loop;
        }

        /// <summary>Total length in seconds (0 when unknown).</summary>
        public static float Length(string key)
        {
            var d = Durations(key);
            if (d == null) return 0f;
            int sum = 0;
            foreach (int ms in d) sum += ms;
            return sum / 1000f;
        }

        /// <summary>Frame index for an animation that started <paramref name="elapsed"/> seconds ago.</summary>
        public static int FrameAt(string key, float elapsed, bool loop, int holdFrame = -1)
        {
            var d = Durations(key);
            if (d == null || d.Length == 0) return 0;
            int total = 0;
            foreach (int ms in d) total += ms;
            int t = Mathf.Max(0, Mathf.FloorToInt(elapsed * 1000f));
            if (loop) t %= Mathf.Max(1, total);
            int acc = 0;
            for (int i = 0; i < d.Length; i++)
            {
                acc += d[i];
                if (t < acc) return (holdFrame >= 0 && i > holdFrame) ? holdFrame : i;
            }
            return holdFrame >= 0 ? holdFrame : d.Length - 1;
        }
    }

    /// <summary>One actor's current animation (hero or monster).</summary>
    public class AnimState
    {
        public string actor;          // "hero" or monster id
        public string anim = "idle";
        public float start;
        public int holdFrame = -1;    // freeze on this frame (bullet-time wind-up)
        public string next = "idle";  // played when a one-shot finishes

        public string Key => actor + "_" + anim;

        public void Play(string a, string then = "idle", int hold = -1)
        {
            anim = a; start = Time.time; next = then; holdFrame = hold;
        }

        /// <summary>Release a held wind-up so the remaining frames play.</summary>
        public void Release()
        {
            if (holdFrame < 0) return;
            var d = AnimLibrary.Durations(Key);
            int skip = 0;
            if (d != null) for (int i = 0; i <= holdFrame && i < d.Length; i++) skip += d[i];
            start = Time.time - skip / 1000f;
            holdFrame = -1;
        }

        public int CurrentFrame()
        {
            bool loop = AnimLibrary.Loops(Key);
            float el = Time.time - start;
            if (!loop && holdFrame < 0 && el >= AnimLibrary.Length(Key) && next != null && anim != next)
            {
                Play(next, next);
                el = 0f;
                loop = AnimLibrary.Loops(Key);
            }
            return AnimLibrary.FrameAt(Key, el, loop, holdFrame);
        }
    }

    public class VfxInstance
    {
        public string name;   // vfx/<name>.png
        public Vector2 center;
        public float size;
        public float start;
        public Color tint = Color.white;
    }

    public class FloatingText
    {
        public string text;
        public Vector2 pos;
        public Color color;
        public float start;
        public float life = 1.1f;
        public int fontSize = 26;
    }

    public static class GuiSprite
    {
        /// <summary>Draws frame <paramref name="frame"/> of a horizontal strip into <paramref name="r"/>.</summary>
        public static void DrawFrame(Rect r, Texture2D tex, int frame, Color tint)
        {
            if (tex == null) return;
            int n = Mathf.Max(1, tex.width / Mathf.Max(1, tex.height));
            frame = Mathf.Clamp(frame, 0, n - 1);
            Color prev = GUI.color;
            GUI.color = tint;
            GUI.DrawTextureWithTexCoords(r, tex, new Rect((float)frame / n, 0f, 1f / n, 1f), true);
            GUI.color = prev;
        }

        public static int FrameCount(Texture2D tex) => tex == null ? 1 : Mathf.Max(1, tex.width / Mathf.Max(1, tex.height));

        // Easing (motion-design skill: entrances decelerate, exits accelerate)
        public static float EaseOutCubic(float t) { t = Mathf.Clamp01(t); return 1f - Mathf.Pow(1f - t, 3f); }
        public static float EaseOutBack(float t)
        {
            t = Mathf.Clamp01(t);
            const float c1 = 1.70158f, c3 = c1 + 1f;
            return 1f + c3 * Mathf.Pow(t - 1f, 3f) + c1 * Mathf.Pow(t - 1f, 2f);
        }
    }
}
